import React, { forwardRef } from 'react';

import { MarkersGroup } from './MarkersGroup.js';
import { AnnotationsTooltip } from './tooltip/AnnotationsTooltip.js';
import { AnnotationsAtom } from '../../annotations-atoms/AnnotationsAtom.js';
import { TrackAtom } from '../../annotations-atoms/components/TrackAtom.js';
import { useAnnotationsSelectionState } from '../hooks/store/selectors.js';
import { useSetStateSelection } from '../hooks/store/state-setters.js';
import { useAnnotationsData } from '../hooks/useAnnotationsData.js';
import { useAnnotationsRenderer } from '../hooks/useAnnotationsRenderer.js';
import { useMarkersInteractions } from '../hooks/useMarkersInteractions.js';

type AnnotationsContentProps = {
  width: number;
  height?: number;
  labelsOffset: number;
};

export const AnnotationsContent = /* @__PURE__ */ forwardRef<
  SVGSVGElement,
  AnnotationsContentProps
>(({ width, height, labelsOffset }, forwardedRef) => {
  const { showLabels } = useAnnotationsRenderer();

  const { tooltipGrouping } = useAnnotationsData();
  const updateSelection = useSetStateSelection();
  const { pinnedGroup } = useAnnotationsSelectionState();
  const { onMarkersInteraction } = useMarkersInteractions();

  return (
    <>
      <AnnotationsAtom
        width={width}
        height={height}
        labelsWidth={labelsOffset}
        showLabels={showLabels}
        ref={forwardedRef}
      >
        {tooltipGrouping.map((trackData, index) => {
          const currentTrack = Array.from(trackData.markers.entries());
          const handleMouseEnter = () => {
            if (pinnedGroup !== undefined) {
              return;
            }

            updateSelection({ hoveredTrack: index });
            onMarkersInteraction?.({ hoveredTrack: index });
          };

          return (
            <TrackAtom
              key={index}
              label={trackData.label}
              onMouseEnter={handleMouseEnter}
              hidden={trackData.hidden}
            >
              {currentTrack.map(([groupId, annotationsGroup]) => (
                <MarkersGroup
                  groupId={groupId}
                  annotationsGroup={annotationsGroup}
                  key={groupId}
                  trackNumber={index}
                />
              ))}
            </TrackAtom>
          );
        })}
      </AnnotationsAtom>
      <AnnotationsTooltip />
    </>
  );
});

AnnotationsContent['displayName'] = 'AnnotationsContent';
